import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        List<Integer> nu = new ArrayList<>();
        while (n > 0) {
            nu.add((int)(n % k));
            n /= k;
        }

        int size = k + 1;
        long MOD = 1000000007;

        long[][] a = new long[size][size];
        for (int j = 0; j <= k; ++j) {
            a[0][j] = 1;
            a[j][j] = 1;
        }

        // Function to multiply matrices
        class MatrixOperations {
            long[][] multiply(long[][] A, long[][] B) {
                long[][] res = new long[size][size];
                for (int i = 0; i < size; ++i) {
                    for (int j = 0; j < size; ++j) {
                        long sum = 0;
                        for (int t = 0; t < size; ++t) {
                            sum += A[i][t] * B[t][j];
                        }
                        res[i][j] = sum % MOD;
                    }
                }
                return res;
            }

            long[][] power(long[][] base, long exp) {
                long[][] result = new long[size][size];
                for (int i = 0; i < size; ++i) {
                    result[i][i] = 1;
                }
                while (exp > 0) {
                    if ((exp & 1) == 1) {
                        result = multiply(result, base);
                    }
                    base = multiply(base, base);
                    exp >>= 1;
                }
                return result;
            }

            long[][] jia(long[][] x, int d) {
                long[][] ret = new long[size][size];
                for (int i = 0; i <= k; ++i) {
                    for (int j = 0; j <= k; ++j) {
                        int ni = (i + d) % k;
                        int nj = (j + d) % k;
                        if (i == k) ni = k;
                        if (j == k) nj = k;
                        ret[ni][nj] = x[i][j];
                    }
                }
                return ret;
            }
        }

        MatrixOperations mo = new MatrixOperations();

        long[][] A = new long[size][size];
        for (int j = 0; j <= k; ++j) A[0][j] = 1;
        for (int j = 0; j <= k; ++j) A[j][j] = 1;

        long[][] baseA = A;
        long[][] powA = A;

        long[][] ans = new long[size][size];
        for (int i = 0; i < size; ++i) ans[i][i] = 1;

        long idx = 0;
        for (int i = nu.size() - 1; i >= 0; --i) {
            int currentNu = nu.get(i);
            for (int j = 0; j < currentNu; ++j) {
                ans = mo.multiply(ans, mo.jia(baseA, (int)((j + idx) % k)));
            }
            idx = (idx + currentNu) % k;
        }

        long result = 0;
        for (int i = 0; i <= k; ++i) {
            result = (result + ans[i][k]) % MOD;
        }

        System.out.println(result);
    }
}
